function campaignEligibility(u,c){if(c.status!=='active')return 'الحملة غير منشورة';const n=Date.now(),st=parseJordanDate(c.startAtJordan||c.startAt),en=parseJordanDate(c.endAtJordan||c.endAt);if(st&&n<st)return 'الحملة لم تبدأ بعد';if(en&&n>en)return 'انتهت مدة الحملة';const cfg=packageConfigFor(c,u.package||'Free');if(!cfg||cfg.eligible!==true)return 'الباقة الحالية لا تسمح بهذه الحملة';if(cfg.startsAtJordan&&n<parseJordanDate(cfg.startsAtJordan))return 'المهمة غير متاحة لهذه الباقة بعد';if(cfg.endsAtJordan&&n>parseJordanDate(cfg.endsAtJordan))return 'انتهت إتاحة المهمة لهذه الباقة';if(cfg.levelMinId&&levelRank(u)<levelById(cfg.levelMinId).rank)return 'مستوى الحساب غير كافٍ';if(Array.isArray(c.allowedCountries)&&c.allowedCountries.length&&!c.allowedCountries.includes(u.country))return 'الحملة غير متاحة في دولتك';if(c.targeting?.cities?.length&&!c.targeting.cities.includes(u.city))return 'الحملة غير متاحة في مدينتك';if(c.targeting?.genders?.length&&!c.targeting.genders.includes(u.gender))return 'الحملة غير متاحة حسب الاستهداف';if(c.targeting?.minAge||c.targeting?.maxAge){const age=Math.floor((Date.now()-new Date(u.dateOfBirth).getTime())/31557600000);if(!Number.isFinite(age)||(c.targeting.minAge&&age<c.targeting.minAge)||(c.targeting.maxAge&&age>c.targeting.maxAge))return 'الحملة غير متاحة حسب العمر'}return null}
function eligible(u,t){if(!t.active)return 'المهمة غير متاحة';const n=Date.now(),st=parseJordanDate(t.startsAtJordan||t.startsAt),en=parseJordanDate(t.endsAtJordan||t.endsAt);if(st&&n<st)return t.showBeforeStart?'مهمة إضافية قادمة':'المهمة لم تبدأ بعد';if(en&&n>en)return 'انتهت مدة المهمة';if(t.levelMinId&&levelRank(u)<levelById(t.levelMinId).rank)return 'مستوى الحساب غير كافٍ';if(!t.levelMinId&&levelRank(u)<minRank(t))return 'مستوى الحساب غير كافٍ';const order={Free:0,Plus:1,Premium:2};if(order[u.package||'Free']<order[t.packageMin||t.package||'Free'])return 'الباقة الحالية لا تسمح بهذه المهمة';return null}
