function ensureV17(){
  db.settings=db.settings||{};
  Object.assign(db.settings,{withdrawalFeePercent:db.settings.withdrawalFeePercent??0,withdrawalFeeFixed:db.settings.withdrawalFeeFixed??0,featureFlags:db.settings.featureFlags||{},maintenanceMessage:db.settings.maintenanceMessage||'Tasko قيد الصيانة مؤقتاً.'});
  db.errors=db.errors||[];db.notes=db.notes||[];db.archived=db.archived||{users:[],campaigns:[],tasks:[],withdrawals:[]};db.savedFilters=db.savedFilters||[];db.backups=db.backups||[];
  db.users.forEach(u=>{u.emailVerified=!!u.emailVerified;u.phoneVerified=!!u.phoneVerified;u.levelId=level(u).id;u.sessionVersion=u.sessionVersion||1;u.archived=!!u.archived});
}
ensureV17();
function v17Error(code,message,meta={}){db.errors.unshift({id:id('ERR'),code,message,meta,at:now()});db.errors=db.errors.slice(0,2000);save()}
function v17Page(arr,pq){const page=Math.max(1,Number(pq.page)||1),size=Math.min(100,Math.max(10,Number(pq.size)||25));return {items:arr.slice((page-1)*size,page*size),total:arr.length,page,size,pages:Math.ceil(arr.length/size)}}
function v17Confirm(a,b,double=false){const c=requireConfirm(a,b);if(c)return c;if(double&&String(b.confirm2||'')!==String(b.confirm||''))return 'لإجراء عالي الخطورة يجب تأكيد الرمز مرتين.';return null}
function v17Audit(a,action,target,before,after,reason=''){audit(a,action,target,{before,after,reason});}
function v17Workflow(entity,from,to,actor,target,meta={}){const x={id:id('wf'),entity,from,to,actorId:actor?.id||'system',targetId:target,meta,at:now()};db.activities.unshift({id:x.id,activityType:'workflow',type:`${entity}_${to}`,referenceId:target,status:to,actorId:x.actorId,at:x.at,meta});return x}

async function verifyTurnstile(token,req){if(!process.env.TASKO_TURNSTILE_SECRET)return true;if(!token)return false;try{const r=await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({secret:process.env.TASKO_TURNSTILE_SECRET,response:String(token),remoteip:clientKey(req)})});const d=await r.json();return !!d.success}catch{return false}}
function recordHealthIssue(issue){
  db.healthIssues=db.healthIssues||[]; const existing=db.healthIssues.find(x=>x.fingerprint===issue.fingerprint&&x.status==='open');
  if(existing){existing.lastCheckedAt=now();existing.checks=(existing.checks||0)+1;return existing}
  const x={id:id('ERR'),referenceId:id('HLT'),status:'open',firstSeenAt:now(),lastCheckedAt:now(),severity:issue.severity||'Low',fingerprint:issue.fingerprint||JSON.stringify(issue),...issue};
  db.healthIssues.unshift(x);db.errors=db.errors||[];db.errors.unshift({id:x.id,code:x.referenceId,message:x.problem,at:x.firstSeenAt,resolved:false,health:true});return x;
}
function resolveHealthIssue(fingerprint){const x=(db.healthIssues||[]).find(z=>z.fingerprint===fingerprint&&z.status==='open');if(x){x.status='resolved';x.resolvedAt=now();x.resolution='Automatic health check no longer detects the issue.';const e=(db.errors||[]).find(z=>z.id===x.id);if(e)e.resolved=true;}return x}
function runHealthChecks(){
  db.healthChecks=db.healthChecks||[];db.healthIssues=db.healthIssues||[];db.securityEvents=db.securityEvents||[];
  const checks=[];
  const required=['users','tasks','attempts','campaigns','withdrawals','transactions','referrals'];
  for(const k of required)if(!Array.isArray(db[k]))checks.push({severity:'Critical',fingerprint:'missing:'+k,problem:'Required data collection is missing: '+k,location:'database'});else resolveHealthIssue('missing:'+k);
  for(const u of db.users){if(u.role==='user'&&Number(u.xp||0)<0)checks.push({severity:'High',fingerprint:'negative-xp:'+u.id,problem:'Negative XP detected',location:'user:'+u.id,affectedEntity:u.id});else resolveHealthIssue('negative-xp:'+u.id);if(Number(u.points||0)<0||Number(u.cash||0)<0)checks.push({severity:'Critical',fingerprint:'negative-balance:'+u.id,problem:'Negative user balance detected',location:'user:'+u.id,affectedEntity:u.id});else resolveHealthIssue('negative-balance:'+u.id)}
  for(const c of db.campaigns){if(c.status==='active'&&(!c.packageConfigs||['Free','Plus','Premium'].some(k=>!c.packageConfigs[k])))checks.push({severity:'High',fingerprint:'campaign-config:'+c.id,problem:'Active campaign is missing package configuration',location:'campaign:'+c.id,affectedEntity:c.id});else resolveHealthIssue('campaign-config:'+c.id)}
  const pending=db.withdrawals.filter(w=>['pending','processing'].includes(w.status));for(const w of pending){if(Number(w.amount||0)<=0)checks.push({severity:'High',fingerprint:'withdrawal-amount:'+w.id,problem:'Withdrawal has invalid amount',location:'withdrawal:'+w.id,affectedEntity:w.id});else resolveHealthIssue('withdrawal-amount:'+w.id)}
  for(const x of checks)recordHealthIssue(x);
  const snap={id:id('HC'),at:now(),timezone:'Asia/Amman',status:checks.some(x=>x.severity==='Critical')?'critical':checks.length?'issues':'ok',issues:checks.length,counts:{users:db.users.length,campaigns:db.campaigns.length,attempts:db.attempts.length,withdrawals:db.withdrawals.length,transactions:db.transactions.length}};db.healthChecks.unshift(snap);db.healthChecks=db.healthChecks.slice(0,500);save();return snap;
}
function startHealthScheduler(){if(global.__taskoHealthTimer)return;global.__taskoHealthTimer=setInterval(()=>{try{runHealthChecks()}catch(e){db.errors=db.errors||[];db.errors.unshift({id:id('ERR'),code:'HEALTH_CHECK_FAILED',message:String(e.message||e),at:now(),resolved:false});save()}},Math.max(60000,Number(db.settings.healthCheckIntervalMinutes||5)*60000));setTimeout(()=>{try{runHealthChecks()}catch{}},1000)}

